def f(grid):
    H,W=len(grid),len(grid[0])
    # find bounding boxes of connected components of non-background colors
    from collections import deque
    seen=[[False]*W for _ in range(H)]; comps=[]
    bg=grid[0][0] if True else None
    for i in range(H):
        for j in range(W):
            if seen[i][j] or grid[i][j]==bg: continue
            c=deque([(i,j)]); seen[i][j]=True; cells=[]; col=grid[i][j]
            while c:
                a,b=c.popleft(); cells.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and not seen[x][y] and grid[x][y]!=bg:
                        seen[x][y]=True; c.append((x,y))
            comps.append(cells)
    out=[row[:] for row in grid]
    for cells in comps:
        rs=[a for a,b in cells]; cs=[b for a,b in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        h=r1-r0+1; w=c1-c0+1
        full=len(cells)==2*(h+w)-4 and len(cells)>0
        # filled rect
        filled=cells=={(r,c) for r in range(r0,r1+1) for c in range(c0,c1)}
        if full or filled:
            for (a,b) in cells: out[a][b]=3
    return out
