                stack=[(i,j)]; seen[i][j]=True; c=[(i,j)]
                while stack:
                    a,b=stack.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]!=0:
                            seen[x][y]=True; stack.append((x,y)); c.append((x,y))
                rs=[a for a,b in c]; cs=[b for a,b in c]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                filled=len(c)==(r1-r0+1)*(c1-c0+1)
                h,w=r1-r0+1,c1-c0+1
                border=h+w-2
